def logo_disc(fill, clip_id):
    """白色內圓＋藍色背景區塊（白色留白即貓頭剪影）。"""
    clip = f'<clipPath id="{clip_id}"><circle cx="79.5" cy="79.5" r="75.2"/></clipPath>'
    return clip, f'<path d="{LOGO_BG}" fill="{fill}" clip-path="url(#{clip_id})"/>'


def logo_mark(size=512, name="brand_logo"):
    clip, disc = logo_disc(BRAND_BLUE, "logoClip")
    b = f'<circle cx="79.5" cy="79.5" r="79.5" fill="{BRAND_BLUE}"/><circle cx="79.5" cy="79.5" r="77.6" fill="#FFFFFF"/>' + disc
    return Sprite(name, size, size, "0 0 160 160", b, clip)


ULT_COLORS = {
    # 外圈、背景漸層（亮→暗）、光暈
    "orange": ("#FFE07A", "#FFB300", "#FF6D00", "#FFD54F"),
    "black": ("#D9CCFF", "#8E6BFF", "#3A2A8C", "#B39DFF"),
}


def ult_button(kind):
    rim, c0, c1, glow = ULT_COLORS[kind]
    clip, disc = logo_disc(f"url(#ug{kind})", f"uc{kind}")
    defs = f'<radialGradient id="ug{kind}" gradientUnits="userSpaceOnUse" cx="64" cy="56" r="120"><stop offset="0" stop-color="{c0}"/><stop offset="1" stop-color="{c1}"/></radialGradient>' + clip
    b = f'<circle cx="79.5" cy="79.5" r="78" fill="{glow}" opacity="0.55" filter="url(#softGlow)"/>'
    b += f'<circle cx="79.5" cy="79.5" r="77" fill="{rim}"/>'
    b += '<circle cx="79.5" cy="79.5" r="73" fill="#FFFFFF"/>'
    b += f'<g transform="translate(79.5 79.5) scale(0.96) translate(-79.5 -79.5)">{disc}</g>'
    return Sprite(f"ult_btn_{kind}", 220, 220, "0 0 160 160", b, defs)


def all_sprites():
    return [logo_mark(), ult_button("orange"), ult_button("black")]
